css:
.print-format { padding: 15mm 12mm; margin: 0; font-family: Arial, Helvetica, sans-serif; color: #000; }
.print-format .jc-header { text-align: center; margin-bottom: 10px; }
.print-format .jc-logo { max-height: 60px; max-width: 220px; margin: 0 auto 6px; display: block; }
.print-format .jc-company { font-size: 15pt; font-weight: bold; color: #002060; letter-spacing: 0.5px; }
.print-format .jc-title { font-size: 13pt; font-weight: bold; color: #fff; background: #002060; padding: 6px; margin: 12px 0; text-align: center; letter-spacing: 1px; }
.print-format table.jc-table { width: 100%; border-collapse: collapse; margin-bottom: 6px; table-layout: fixed; }
.print-format table.jc-table td { border: 1px solid #000; padding: 6px 8px; vertical-align: middle; font-size: 10pt; box-sizing: border-box; }
.print-format table.jc-table td.label { width: 30%; font-weight: bold; background: #f2f2f2; white-space: nowrap; }
.print-format table.jc-table td.value { width: 70%; word-wrap: break-word; }
.print-format table.jc-table td.section { background: #002060; color: #fff; font-weight: bold; padding: 5px 8px; font-size: 10pt; letter-spacing: 0.5px; border: 1px solid #002060; }
.print-format .jc-signature { width: 100%; margin-top: 30px; border-collapse: collapse; }
.print-format .jc-signature td { width: 50%; text-align: center; font-size: 10pt; border: none; padding-top: 20px; vertical-align: bottom; }
.print-format .jc-sign-line { border-top: 1px solid #000; width: 80%; margin: 0 auto 8px; }
.print-format .jc-footer { text-align: center; font-size: 8pt; color: #555; margin-top: 14px; border-top: 1px solid #ccc; padding-top: 6px; }
.print-format .jc-barcode { text-align: center; margin: 10px 0 0; }
.print-format .jc-barcode div { font-size: 9pt; font-weight: bold; letter-spacing: 1px; margin-top: 2px; }
